/* المُلهم، «تعلّم»: مكتبة المؤلفين، كتاب «القراءة المثمرة» */
window.HH_LIB=window.HH_LIB||{};
window.HH_LIB["read"]={"id":"read","title":"القراءة المثمرة","sub":"مفاهيم وآليات","author":"أ. د. عبدالكريم بكار","coauthors":[],"translator":"","publisher":"دار القلم، دمشق؛ الدار الشامية، بيروت","year":"1429ه، 2008م","edition":"السادسة","series":"كتب قيمة (27)","lead":"رسالة موجزة ترسم طريق القراءة النافعة: من الدافع والعادة والوقت، إلى خمسة أنواع للقراءة هي الاكتشافية والسريعة والانتقائية والتحليلية والمحورية، ثم تطبقها على قراءة كتب التاريخ. ويرى مؤلفها أن «الولع بالمزيد من الاطلاع، واصطحاب الكتاب هو أحد الحلول المهمة للأزمة الحضارية التي تعاني منها أمة الإسلام.»","audience":"الشباب والمعلمون وطلاب الجامعات والباحثون والقراء الجادون","bio":"","chapters":[{"k":"c1","t":"التعلُّم مدى الحياة","q":"لماذا يحتاج الإنسان إلى أن يتعلم ويقرأ طوال عمره؟","essence":"المعرفة تتجدد فلا يكفي ما تعلمناه","kw":["التعلم المستمر","شيخوخة المعلومات","وسائل الإعلام"],"sections":[{"t":"من النقل إلى الكتابة","pg":7,"key":"وحين صار للغات أبجديات، وتمتع الإنسان بنعمة الكتابة انتقلت المعرفة من حيز الزمان إلى حيز المكان","p":["كان العلم في القديم يقوم على (النقل)، فكان التعلم والتعليم عبارة عن أفعال مقترنة بالزمان"],"items":[{"h":"فطرة التساؤل","x":"فطر الله الإنسان على التساؤل وحب الاستكشاف، فلا يجد حداً للارتواء من المعرفة."},{"h":"تاريخ جديد","x":"بالكتابة صار الحفظ والتوثيق والنشر متاحاً على أوسع نطاق، فتطورت المعارف على نحو مدهش."}]},{"t":"دواعي التعلم مدى الحياة","pg":8,"key":"إن جهلنا ينبسط مع تقدم المعرفة، كما ينبسط سطح التماس لكرة ما مع العالم الخارجي عندما يكبر قطرها، وهذا يشكل تحدياً متزايداً لكل قارئ.","p":["المثقف الذي يرغب في الحفاظ على قيمة ثقافته وكرامتها، مطالَب بأن يعيد تكوين ثقافته على نحو مستمر ومتجدد."],"items":[{"h":"العلم نفسه","x":"كلما زادت المعرفة اتسعت منطقة المجهول، والتوغل في حقولها يولد دوافع جديدة للتقدم."},{"h":"الرزق والمهنة","x":"تتضاءل المهن والوظائف التي يمكن للأميين ومحدودي الثقافة الاضطلاع بها."},{"h":"نسبية المعارف","x":"قيمة ما نملكه من معارف تتبع قدرتنا على الصمود والمنافسة وحل المشكلات في عالم واحد."},{"h":"البرمجة الثقافية","x":"الثقافة الضحلة تجعل المرء شديد المحلية، والاطلاع المتنوع يعظم الوعي بالمقارنة وامتداد الرؤية."},{"h":"تدفق المعلومات","x":"تراكم منتجات البحث العلمي يجعل ما بحوزتنا من معارف يتقادم بسرعة."}]},{"t":"شيخوخة المعلومات","pg":11,"key":"والعلاج لذلك كله دوام الاطلاع والمتابعة؛ حتى لا يتدهور ما لدينا من معرفة","p":["إن تقادم المعلومات يتجلى في صور شتى، فتارة في ظهور زيفها أو عدم دقتها، وتارة يتجلى في عدم ملاءمتها للخطط الجديدة"],"items":[{"h":"تقديرات ينقلها المؤلف","x":"نحو 90% من المعارف العلمية استحدث في العقود الثلاثة الأخيرة، وعلى المتخصص أن يحسب أن نحو 10 إلى 20% من معلوماته قد شاخ."},{"h":"سرعة الشيخوخة","x":"تشيخ المعلومات بنسبة 10% في اليوم في الجرائد، وفي الشهر في المجلات، وفي السنة في الكتب."}]},{"t":"القراءة ومصادر المعلومات الأخرى","pg":13,"key":"إن وسائل الإعلام تقدم معلومات متشظية، قلما تتصل بالحاجة المعرفية الحقيقية للمتابع لها","p":["فللعقل طاقة محدودة على التحليل والتصنيف والغربلة لما يرد عليه، وحين يزيد على طاقته، فإنه يربكه ويشتته."],"items":[{"h":"ضعف الإقبال على الكتاب","x":"متوسط ما يطبع من معظم الكتب في البلاد العربية لا يتجاوز 3000 نسخة، ولا ينفد غالباً في أقل من 3 سنوات."},{"h":"التفكير بالنيابة","x":"يتلقى المشاهد والمستمع مركباً جاهزاً من البيانات المنتقاة فيستسلم لها دون جهد شخصي."},{"h":"إنصاف","x":"لا ينكر المؤلف أن الدفق الإعلامي أوجد استنارة عامة ورفع درجة الوعي لدى الناس."}]},{"t":"الكتاب وسيلة التثقف الأساسية","pg":14,"key":"وأعتقد أن الكتاب ما زال هو الوسيلة الأساسية للتثقف الجيد، حيث نستطيع أن نمارس حريتنا كاملة في اختيار ما نحتاج إليه","p":["إن الهامش الذي يفصل بين التسلية وبين التثقف الحق هامش ضيّق، ومن السهل أن يكون ما نستمع إليه ونشاهده ضرباً من ضروب التسلية، وتزجية الوقت، ونحن نظن أننا نتعلم."],"items":[{"h":"الأهداف أولاً","x":"لا يقلل المؤلف من شأن المصادر الأخرى؛ فالمهم أن تتضح أهداف التثقف ثم نبحث عن الوسائل التي تبلغنا إياها."}]}],"quiz":[{"q":"لماذا يرى المؤلف أن تقدم المعرفة يزيد حاجتنا إلى مزيد من التعلم؟","o":["لأن منطقة المجهول تتسع كلما زادت المعرفة","لأن المعارف القديمة تفقد قيمتها كلها","لأن الوظائف لم تعد تقبل غير المتخصصين","لأن الكتب الحديثة أيسر كثيراً من الكتب القديمة"],"why":"إن الذي يدعو الإنسان إلى مزيد من التعلم، هو العلم نفسه، إذ إنه كلما زادت المعرفة، اتسعت منطقة المجهول.","pg":8},{"q":"بأي صورة شبّه المؤلف انبساط جهلنا مع تقدم المعرفة؟","o":["سطح تماس كرة يكبر قطرها","نهر يتسع كلما اقترب من مصبه","بناء تعلو طبقاته فوق أساسه","شجرة تتفرع أغصانها كل عام"],"why":"إن جهلنا ينبسط مع تقدم المعرفة، كما ينبسط سطح التماس لكرة ما مع العالم الخارجي عندما يكبر قطرها، وهذا يشكل تحدياً متزايداً لكل قارئ.","pg":8},{"q":"متخصص اكتفى بما حصّله في جامعته قبل سنوات طويلة ولم يتابع جديد مجاله. ما الذي يتوقعه المؤلف له؟","o":["أن يجد نفسه في النهاية خارج التخصص","أن يصير مرجعاً لأن خبرته تراكمت","أن تبقى معلوماته صالحة ما دامت موثقة","أن يتفوق على من يقرأ في غير مجاله"],"why":"وإذا كان متخصصاً فإن أمواج القفزات العلمية في تخصصه ستقذف به نحو الشاطئ، ليجد نفسه في النهاية خارج التخصص.","pg":8},{"q":"بحسب التقدير الذي ينقله المؤلف، أي ما يلي تعتريه أعراض الشيخوخة بنسبة 10% في اليوم؟","o":["ما ينشر في الجرائد","ما ينشر في الكتب","ما ينشر في المجلات","ما تضمه الموسوعات"],"why":"ويرى أحد الباحثين أن أعراض الشيخوخة تعتري المعلومات بنسبة 10% في اليوم بالنسبة إلى الجرائد","pg":11},{"q":"لماذا يبقى الكتاب عند المؤلف الوسيلة الأساسية للتثقف الجيد رغم تطور وسائل الإعلام؟","o":["لأننا نمارس معه حريتنا كاملة في اختيار ما نحتاج","لأنه يقدم المعلومة بأسلوب بلاغي بارع يدهش القارئ","لأنه يقدم بيانات منتقاة تغني القارئ عن التفكير","لأنه الوسيلة الوحيدة التي ترفع الوعي العام"],"why":"وأعتقد أن الكتاب ما زال هو الوسيلة الأساسية للتثقف الجيد، حيث نستطيع أن نمارس حريتنا كاملة في اختيار ما نحتاج إليه","pg":14}],"scene":{"t":"مساء أمام الشاشة","x":"معلم يقضي مساءه كل يوم في متابعة برامج ثقافية متنوعة، ويشعر أنه يتثقف دون أن يعرف ماذا يريد أن يتعلم.","opts":["يحدد أهدافه في التثقف أولاً ثم يختار الوسيلة التي تبلغه إياها","يكتفي بالبرامج لأنها رفعت وعي الناس عامة","يهجر كل الوسائل الأخرى ويقتصر على الكتب وحدها"],"why":"فالمهم دائماً أن تكون أهدافنا في التثقف والارتقاء المعرفي واضحة، ثم نبحث عن الأدوات والوسائل التي تبلغنا إياها.","pg":15}},{"k":"c2","t":"من أجل القراءة","q":"كيف نجعل القراءة جزءاً ثابتاً من حياتنا؟","essence":"دافع وعادة وكتاب ووقت وجو مناسب","kw":["الدافع","عادة القراءة","تنظيم الوقت"],"sections":[{"t":"مسألة مصير","pg":16,"key":"فالمسألة ليست كمالية ولا ترفيهية، وإنما هي مسألة مصير.","p":["لا ريب أن جعل (القراءة) إحدى مفردات أعمالنا اليومية، لن يكون يسيراً؛ حيث يقتضي تغييراً جوهرياً في سلوكاتنا وعاداتنا، كما يتطلب توفير المال والوقت، وقبل ذلك الأهداف والدوافع."],"items":[{"h":"خمسة شروط","x":"الدافع، وتكوين العادة، وتوفير الكتاب، وتوفير الوقت، وتهيئة جو القراءة."}]},{"t":"الدافع","pg":18,"key":"وهذا هو السبب الجوهري في انعدام الدافع نحو القراءة لدى كثير من المسلمين.","p":["وحين يقطع المجتمع شوطاً في طريق الحضارة، فإنه يمارس ضغوطاً مادية وأدبية على أفراده من أجل أن يرفعوا من سوياتهم"],"items":[{"h":"حاجات أساسية وثانوية","x":"التخلف الحضاري يشغل المرء بحاجاته الأساسية ويضعف حسه نحو ما يحسّن نوعية حياته."},{"h":"جهات الدفع","x":"الأسر المتعلمة والمدارس والجامعات والنوادي الأدبية والمكتبات العامة والجمعيات الثقافية."},{"h":"جمعية في كل مدينة","x":"يقترح أن تكون في كل مدينة جماعة مهمتها التشجيع على القراءة والمعاونة على توفير الكتاب."}]},{"t":"تكوين عادة القراءة","pg":19,"key":"البدايات التربوية الجيدة تبدأ دائماً في المنزل، والآباء هم المربون الطبيعيون","p":["البدايات دائماً شاقة، وأشق مراحل الطريق هي المرحلة الأولى"],"items":[{"h":"تسخين السيارة","x":"يسهل الأمر حين نعد البداية مثل تسخين السيارة ثم يتعاظم الانطلاق شيئاً فشيئاً."},{"h":"في البيت","x":"سرد الحكاية وقراءة القصة وشراء سلاسل الكتب المصورة ووجود مكتبة جيدة في المنزل."},{"h":"في المدرسة","x":"لا قيمة لعمل المدرسة إلا إذا كفّت عن التلقين وكلفت الطالب بالرجوع إلى المراجع وتلخيص الكتب ومناقشتها."},{"h":"المتعة","x":"لا تتكون العادة إلا حين يشعر القارئ بالمتعة، وذلك حين تصير القراءة اكتشافاً وتنمية للعقل."}]},{"t":"توفير الكتاب","pg":21,"key":"ستجعلنا نوقن أن السبب الجوهري للعزوف عن القراءة لدى كثير من الناس ليس شح المال، وإنما انعدام أية رغبة لديهم في مصاحبة الكتاب.","p":["لكن عند التمحيص في حياة معظم الناس سنجد أن سوء تنظيم عملية الإنفاق لديهم، هو المسؤول الأول عن شعورهم بالعجز عن توفير ثمن الكتب وغيرها."],"items":[{"h":"مكتبات في كل مكان","x":"إلزام الهيئات والنوادي والنقابات والشركات بإيجاد مكتبات، وتطوير مكتبات المساجد."},{"h":"رابطة لأصدقاء الكتاب","x":"معارض، وسوق للكتاب المستعمل، وطبعات شعبية، وصندوق لدعم الكتب القيمة، وتأجير الكتاب."},{"h":"الإعارة وكتب الجيب","x":"نظام وطني لإعارة الكتاب وتبادله، وسلاسل تبسط العلوم لا تستهدف الربح."},{"h":"ميزانية الأسرة","x":"تخصيص 2% من مصروف الأسرة يكفي لعدد من الكتب شهرياً ولمكتبة قيمة على المدى البعيد."}]},{"t":"توفير الوقت للقراءة","pg":24,"key":"إن الوقت هو المادة التي صُنعت منها الحياة","p":["إن الإحساس بالزمان منتَج حضاري"],"items":[{"h":"عذر شائع","x":"أكثر من 80% ممن لا يقرؤون كتاباً في الشهر يعتذرون بأنه ليس لديهم وقت."},{"h":"سجل أسبوع","x":"من يسجل أوقاته أسبوعاً يجد أن نحو 20% على الأقل من نشاطاته لا يخدم أي هدف."},{"h":"نصف ساعة","x":"تنظيم المكالمات الهاتفية وحده كفيل بأن يوفر نصف ساعة يومياً للقراءة."},{"h":"الساعة الذهبية والهادئة","x":"وقت قمة النشاط للمواد الصعبة، وساعة لا يستقبل فيها المرء زائراً ولا يرد على هاتف."},{"h":"المثابرة","x":"تغيير السلوك مع الوقت يحتاج إلى وقت، وعلينا أن نثابر ولا نيأس."}]},{"t":"تهيئة جو القراءة","pg":26,"key":"إن هناك ارتباطاً وثيقاً بين إمكانية الفهم والاستيعاب وبين الأجواء والأوضاع التي تجري فيها عملية القراءة","p":["إن المكان المليء بالأشياء المبعثرة، أو التي لا حاجة إليها؛ يبعث على الكآبة، ويولّد الرغبة في مغادرته."],"items":[{"h":"مكان منظم جميل","x":"ويحسن أن تخصص الدقائق الأخيرة من الجلسة لترتيب المكان والاستعداد للجلسة التالية."},{"h":"حجرة صحية","x":"حسنة التهوية جيدة الإضاءة، وحرارتها بين 15 و21 درجة."},{"h":"الهدوء","x":"بعيداً عن الضوضاء، وإلا امتزجت الدراسة بالتسلية، والعمل بالفراغ."},{"h":"الأدوات في متناول اليد","x":"كرسي مريح، والمعاجم والمراجع على المكتب."},{"h":"الاستراحة","x":"العبرة بالإنتاجية لا بكثرة الجلوس، وكتيبة المشاة تمشي يوماً كاملاً إذا استراحت عشر دقائق كل ساعة."}]}],"quiz":[{"q":"ما السبب الجوهري لانعدام الدافع نحو القراءة لدى كثير من المسلمين في رأي المؤلف؟","o":["انشغال المرء بحاجاته الأساسية بفعل التخلف الحضاري","غلاء الكتب الدائم وعدم توفر المال المطلوب لشرائها","طول ساعات العمل اليومي وقلة أوقات الفراغ","جاذبية برامج وسائل الإعلام وزخرفتها العالية"],"why":"فالتخلف الحضاري، يجعل المرء مشغولاً بتلبية حاجاته الأساسية","pg":17},{"q":"رجل يشكو دائماً من أنه لا يجد مالاً لشراء الكتب. ما الذي يكشفه التمحيص غالباً في حال معظم الناس؟","o":["أن العلة سوء تنظيم الإنفاق","أن أسعار الكتب تفوق الدخل فعلاً","أن المكتبات العامة غير متاحة","أن الكتب المستعملة لا تصلح للقراءة"],"why":"لكن عند التمحيص في حياة معظم الناس سنجد أن سوء تنظيم عملية الإنفاق لديهم، هو المسؤول الأول عن شعورهم بالعجز عن توفير ثمن الكتب وغيرها.","pg":21},{"q":"كم يرى المؤلف أن تخصص الأسرة من مصروفها لتأسيس مكتبة قيمة في المنزل على المدى البعيد؟","o":["2% من المصروف","5% من المصروف","10% من المصروف","20% من المصروف"],"why":"إن تخصيص 2% من مصروف أية أسرة، كافٍ لتأمين عدد من الكتب متوسطة الحجم شهرياً، وتأسيس مكتبة قيمة في المنزل على المدى البعيد.","pg":23},{"q":"ما المقصود بعبارة (الساعة الذهبية) في اليوم كما يصفها المؤلف؟","o":["وقت يكون فيه المرء في قمة نشاطه","ساعة لا يستقبل فيها زائراً ولا هاتفاً","نصف ساعة يوفرها تنظيم المكالمات","دقائق أخيرة لترتيب مكان الدراسة"],"why":"سيكون مفيداً ونحن نبحث عن وقت للقراءة أن نكتشف (الساعة الذهبية) في يومنا، حيث يكون الواحد منا في قمة نشاطه","pg":25},{"q":"لماذا ينصح المؤلف بأن يضع القارئ على مكتبه المعاجم والمراجع التي يحتاج إليها؟","o":["حتى لا يضيع الوقت بالقيام والقعود","حتى يبدو المكان منظماً وجميلاً للزائر","حتى تبقى الحجرة حسنة التهوية والإضاءة","حتى يقرأ بصوت مرتفع دون أن يقاطعه أحد"],"why":"حتى لا يضيع الوقت بالقيام والقعود، وحتى لا يعطي لنفسه المسوِّغ للانقطاع عن القراءة.","pg":28}],"scene":{"t":"أربع ساعات بلا توقف","x":"طالب يجلس للمذاكرة أربع ساعات متصلة دون أي توقف، ثم يشكو أنه لا يستوعب شيئاً في الساعة الأخيرة.","opts":["يجعل أوقاتاً للاستراحة ينشغل فيها بغير التفكير في المعلومات","يطيل الجلوس أكثر لأن العبرة بكثرة الساعات","يزيد عدد الكتب التي يقرؤها في الجلسة الواحدة"],"why":"وهذا لا يمكن الحصول عليه إلا من خلال جعل أوقات للاستراحة، والانشغال بشيء غير التفكير والتعامل مع المعلومات.","pg":28}},{"k":"c3","t":"لماذا نقرأ","q":"ما الأهداف التي يقرأ الناس من أجلها، وأيها أنفع؟","essence":"تسلية أو معلومات أو توسيع للفهم","kw":["أهداف القراءة","التسلية","توسيع الفهم"],"sections":[{"t":"القراءة والحضارة","pg":29,"key":"والحضارة ليست في جوهرها الوصول إلى معلومات جديدة، وإنما توظيف المعارف المتاحة في تحسين نوعية حياة الناس، والارتقاء بجوانبها المختلفة","p":["الظروف الحياتية التي يمر بها كل واحد منا، تجعل الأهداف الباعثة على القراءة تتفاوت تفاوتاً بعيداً"],"items":[{"h":"تحديد الهدف","x":"كثير من الناس لا يعرف لماذا يقرأ، مع أن تحديد الهدف مهم لاختيار نوع الكتاب ونوع القراءة ومستواها."}]},{"t":"القراءة من أجل التسلية","pg":30,"key":"وهذه القراءة الأكثر شيوعاً بين الناس.","p":["وتثبت بعض الإحصاءات أن نحواً من 70% من القراء يتجهون إلى القراءة من أجل التسلية"],"items":[{"h":"سر شيوعها","x":"لا تحتاج إلى مهارة ولا تكلف جهداً، ويلقي القارئ الكتاب متى شاء."},{"h":"بلا محاور","x":"السواد الأعظم لا يملك أهدافاً تلزمه بنوع معين من الكتب، فيقرأ أي شيء يقع تحت يده."},{"h":"لا تخلو من فائدة","x":"تملأ الفراغ بما لا يضر، وقد تكون علاجاً للخرف والتمركز الشديد حول الذات؛ فصحبة الكتاب خير على كل حال."}]},{"t":"القراءة من أجل المعلومات","pg":32,"key":"إن القراءة من أجل الحصول على معلومات شائعة جداً؛ لأن في عالمنا الإسلامي (حمّى) تجتاح كثيراً من الناس، هي حمّى البحث عن الأسهل، والوصول إليه بأسرع وقت ممكن!","p":["وليس من الغريب أن نصف شخصاً ما بأنه كثير القراءة، ثم نجد أن (مركّبه العقلي) لم يطرأ عليه أي تغير خلال عشرين سنة من القراءة والاطلاع!"],"items":[{"h":"جهد محدود","x":"يضيف القارئ معلومة إلى معلوماته دون أن يرتقي فهمه أو قدرته على المحاكمة والغربلة."}]},{"t":"القراءة من أجل توسيع قاعدة الفهم","pg":33,"key":"ولذا فإن الكتاب الذي يحسّن الفهم، هو كتاب يتحدى ولا يعجز","p":["فالكتاب الذي يرقى بفهم قارئه ليس ذلك الكتاب المفهوم لديه، أو ذلك الذي يعرض معلومات وأفكاراً معروفة، وإنما ذلك الكتاب الذي يشعر قارئه أنه أعلى من مستواه، وأن فهمه يحتاج إلى نوع من العناء والجدية والتركيز."],"items":[{"h":"أشقها وأنفعها","x":"هي أشق أنواع القراءة وأكثرها فائدة، والذين يقرؤون لأجلها قلة."},{"h":"الذهب ومنجمه","x":"مكاسب كتب المعلومات كقطعة ذهبية، ومكاسب كتب تحسين الفكر كمفتاح منجم من الذهب."},{"h":"حد غامض","x":"كتاب المعلومات قد يحسّن الفهم إذا قدم بسرد جديد فيه استدلالات ومقارنات وتعليلات."}]}],"quiz":[{"q":"أي أهداف القراءة الثلاثة يعدّه المؤلف أشقها وأكثرها فائدة؟","o":["توسيع قاعدة الفهم","الاطلاع على المعلومات","التسلية وتزجية الوقت","تلبية التطور المهني"],"why":"القراءة من أجل توسيع قاعدة الفهم، وهي أشق أنواع القراءة وأكثرها فائدة.","pg":32},{"q":"بحسب بعض الإحصاءات التي يذكرها المؤلف، ما نسبة القراء الذين يتجهون إلى القراءة من أجل التسلية؟","o":["نحو 70%","نحو 20%","نحو 80%","نحو 50%"],"why":"وتثبت بعض الإحصاءات أن نحواً من 70% من القراء يتجهون إلى القراءة من أجل التسلية","pg":30},{"q":"ما موقف المؤلف من القراءة التي غايتها تزجية الوقت وملء الفراغ؟","o":["لا تخلو من فائدة وصحبة الكتاب خير على كل حال","يذمها لأنها تملأ الفراغ بأشياء ضارة غالباً","يقصرها على القصص والروايات والمجلات وحدها","يراها تحتاج إلى مهارة خاصة لا يملكها كثير من الناس"],"why":"وهكذا فصحبة الكتاب خير على كل حال.","pg":31},{"q":"صديقك يقرأ كثيراً منذ عشرين سنة، لكن طريقة تفكيره لم تتغير. بم يفسر الكتاب مثل هذه الحالة؟","o":["بأنه يقرأ ليجمع معلومات لا ليحسّن فهمه","بأنه يقرأ كتباً أعلى كثيراً من مستواه","بأنه أهمل القراءة السريعة فقلّ ما قرأه","بأنه لم يخصص مكاناً هادئاً للقراءة"],"why":"وليس من الغريب أن نصف شخصاً ما بأنه كثير القراءة، ثم نجد أن (مركّبه العقلي) لم يطرأ عليه أي تغير خلال عشرين سنة من القراءة والاطلاع!","pg":32},{"q":"ما صفة الكتاب الذي يرقى بفهم قارئه؟","o":["يتحدى ولا يعجز","مفهوم لدى قارئه","يعرض المعروف","بعيد عن ثقافته"],"why":"ولذا فإن الكتاب الذي يحسّن الفهم، هو كتاب يتحدى ولا يعجز","pg":33}],"scene":{"t":"كتب سهلة دائماً","x":"طالب في المرحلة الثانوية يختار دائماً كتباً يفهمها كلها من القراءة الأولى، ويشعر أنه لا يتقدم.","opts":["يختار كتاباً أعلى من مستواه يحتاج إلى جدية وتركيز","يستمر في الكتب السهلة حتى لا يشعر بالانكسار","يقفز إلى أصعب كتاب في الفلسفة ليتحدى نفسه"],"why":"فهو أعلى من مستوى القارئ لكن يمكن أن يرقى إليه إلى حد مقبول.","pg":33}},{"k":"c4","t":"أنواع القراءة: الاكتشافية والسريعة والانتقائية","q":"كيف نختار الكتاب ونضبط سرعة قراءته وفق حاجتنا؟","essence":"تصفح قبل الشراء وسرعة تناسب الغاية","kw":["التصفح","القراءة السريعة","الانتقاء"],"sections":[{"t":"القراءة الاكتشافية","pg":36,"key":"إن الكتاب مثل (القميص) كثيراً ما تكون جودته من مناسبته للابسه، وليست من جودة قماشه أو لونه.","p":["نستطيع خلال نصف ساعة أن نصل إلى حكم جيد على الكتاب إذا قمنا بالتالي"],"items":[{"h":"المقدمة","x":"تكشف دوافع التأليف وأهدافه والفئة التي يخدمها الكتاب."},{"h":"فهرس الموضوعات","x":"للاطلاع على الموضوعات، والأهم اكتشاف المنظور المنطقي للكتاب."},{"h":"المصادر والمراجع","x":"تدل على طبيعة معالجة المؤلف وخلفيته الفكرية والثقافية."},{"h":"الملخصات وعناوين الفصول","x":"لتحسس جوهر المادة المعروضة."},{"h":"صفحات مختارة","x":"لمعرفة مستوى المعالجة؛ والقراءة المنتظمة تملك القارئ ذائقة معرفية."},{"h":"ثمن الإهمال","x":"إهمال التصفح جعل أعداداً لا تحصى تشتري كتباً لا تستحق القراءة أو لا تهمهم."}]},{"t":"القراءة السريعة","pg":40,"key":"فانتقال البصر قفز، والتركيز يعني التقاط وحدات دلالية ذات مغزى.","p":["مشكلة القارئ غير المتمرس، هي (النكوص) إلى سطور سابقة"],"items":[{"h":"ستون سنة","x":"من قرأ كتاباً كل أسبوع ستين سنة يكون قد قرأ نحو 3000 كتاب، وهو رقم متواضع."},{"h":"قراءتان","x":"كتب تقرأ سريعاً لالتقاط النافع، وكتب تحرث حرثاً كما يفعل الفلاح في أرض خصبة."},{"h":"الفرق في الثانية","x":"البطيء لا يلتقط أكثر من عشر وحدات أو مقاطع صوتية، والسريع يلتقط حتى عشر كلمات دلالية."},{"h":"الإبهام تحت السطر","x":"يضم القارئ إبهامه مع أصبعه ويحركه تحت السطر، فقد تزيد سرعته ضعفين أو ثلاثة."},{"h":"البطاقة المقطوعة","x":"بطاقة فيها مستطيل 4سم في 7مم تخفي ما قرئ فلا يعود إليه."}]},{"t":"الفهم والسرعة والجهر","pg":44,"key":"مما يعني أن استمرار القراءة في محور من محاور المعرفة، سيكون مساعداً أساسياً على قراءة أسرع وإنجاز أعظم.","p":["وذلك لأن القراءة عمل عقلي، يبدأ بالنظر."],"items":[{"h":"السرعة ليست غاية","x":"لا يقرأ كتاب في الفلسفة بسرعة قراءة القصة، والقراءة بسرعة كبيرة إنجاز مشكوك فيه."},{"h":"جهرية ثم صامتة","x":"يبدأ المبتدئ والطفل بالقراءة الجهرية، ثم المهموسة، ثم الصامتة لأنها أسرع."}]},{"t":"القراءة الانتقائية","pg":47,"key":"إن وجود فكرة تربوية في كتاب تاريخي، يعني نوعاً من الامتداد التربوي في العمق التاريخي","p":["وهذا يعطينا دائماً لوناً من ألوان توحيد المعرفة، وإعادة الربط بين فروعها وأجزائها"],"items":[{"h":"كتب الحقل نفسه","x":"المصدر الأساسي للباحث، لكن الاقتصار عليها يعزل الموضوع عن امتداداته في فروع المعرفة الأخرى."},{"h":"كتب من حقول أخرى","x":"كالبحث عن فكرة تربوية في كتاب فقه، وهو صعب كالبحث عن إبرة في كومة من القش."},{"h":"رحلة مثيرة","x":"فائدتها كفوائد رحلة خارج الوطن: لا نعرف ما سنعود به، لكنه كثيراً ما يكون رائعاً."},{"h":"رفرفة فوق النصوص","x":"تحتاج إلى قراءة سريعة جداً يسبقها تحديد دقيق لبغية القارئ."},{"h":"المستعار والمملوك","x":"من الكتاب المستعار تُنقل المعلومات إلى بطاقات، وفي المملوك توضع إشارات حول الفقرات."}]}],"quiz":[{"q":"كم يحتاج القارئ بحسب المؤلف ليصل إلى حكم جيد على كتاب قبل شرائه؟","o":["نصف ساعة","ساعة كاملة","يوم كامل","ربع ساعة"],"why":"نستطيع خلال نصف ساعة أن نصل إلى حكم جيد على الكتاب إذا قمنا بالتالي","pg":36},{"q":"ما الأهم الذي يبحث عنه القارئ حين ينظر في فهرس موضوعات الكتاب؟","o":["المنظور المنطقي للكتاب","مصادر المؤلف ومراجعه","الفئة التي يخدمها الكتاب","خلفية المؤلف الفكرية"],"why":"والأهم من ذلك اكتشاف المنظور المنطقي للكتاب.","pg":37},{"q":"ما المشكلة التي تبطئ القارئ غير المتمرس بحسب الكتاب؟","o":["النكوص إلى سطور سابقة","التقاط وحدات دلالية كثيرة","تحريك اليد تحت السطر","القراءة الصامتة المبكرة"],"why":"مشكلة القارئ غير المتمرس، هي (النكوص) إلى سطور سابقة","pg":40},{"q":"ما الفائدة التي يضيفها وضع الإبهام والسبابة تحت السطر سوى زيادة السرعة؟","o":["زيادة التركيز على ما يقرأ","تحويل القراءة إلى جهرية","حفظ النص كاملاً بعد قراءة واحدة","إبطاء العين لتفهم المعنى"],"why":"فإنه في هذه الحالة لا يساعد نفسه على سرعة القراءة فحسب، وإنما يحسّن تركيزه أيضاً على ما يقرأ","pg":43},{"q":"باحث في التربية يتصفح كتباً في الفقه والتاريخ بحثاً عن أفكار تخدم موضوعه. بم يشبّه المؤلف فائدة هذا النوع من المطالعة؟","o":["رحلة مثيرة خارج حدود الوطن","مفتاح أعطيه صاحبه لمنجم ذهب","قميص يناسب لابسه ويليق به","فلاح يحرث أرضاً خصبة حرثاً"],"why":"إلا أن مما ينبغي التنبه إليه أن فائدة هذا النوع من المطالعة أشبه بالفوائد التي نحصل عليها من وراء رحلة مثيرة خارج حدود الوطن","pg":47}],"scene":{"t":"عنوان مغرٍ في المعرض","x":"معلم يتجول في معرض الكتاب فيجذبه كتاب بعنوان لافت عن التدريس الناجح، وثمنه مرتفع.","opts":["يقرأ مقدمته وفهرسه ومراجعه ويتصفح بعض صفحاته قبل أن يقرر","يشتريه فوراً لأن العنوان يدل على المحتوى","يشتريه لأن مؤلفه مشهور أياً كان موضوعه"],"why":"إن إهمال القراءة الاستكشافية أو التصفحية، قد أدى بأعداد لا تحصى من البشر إلى أن يشتروا كتباً، لا تستحق القراءة","pg":38},"rel":[{"b":"jeel","ci":7,"t":"الفوضى المعرفية وترتيب المنهجية العلمية"}]},{"k":"c5","t":"القراءة التحليلية: سمات القارئ الجيد وأنواع الكتب","q":"كيف يرتقي القارئ إلى أفق الكاتب، وما الكتب التي تستحق ذلك؟","essence":"صبر ومرونة ووعي بالعصر وحسن اختيار","kw":["القراءة التحليلية","القارئ الجيد","أنواع الكتب"],"sections":[{"t":"معنى القراءة التحليلية","pg":49,"key":"إن القراءة التحليلية هي أفضل أسلوب يمكن للمرء أن يتبعه في استكناه مضمون كتاب ما في وقت غير محدد.","p":["والحقيقة أن الكتب التي تستحق كل هذه الفعالية في القراءة ليست كثيرة"],"items":[{"h":"أكثر من الاطلاع","x":"تعني الارتقاء إلى أفق الكاتب ومعرفة مصادره وخلفيته وحواره ونقده."},{"h":"عصر السرعة","x":"ولّد الملل والهروب من القراءة المتأنية، فقرأ كثير من الشباب كتباً سهلة فكان ما استفادوه ضحلاً."}]},{"t":"دور القارئ والنص","pg":52,"key":"إن النص الجيد هو النص الذي يشتمل على فراغات معرفية، وملء هذه الفراغات من الآن فصاعداً صار من مهمة القارئ الجيد","p":["وحين يشرع القارئ في سدها تبدأ رحلة التواصل بينه وبين الكاتب."],"items":[{"h":"الدور السلبي قديماً","x":"كان ينظر إلى القارئ على أنه متلقٍ سلبي، وهو فرع من روح الجمود والتقليد."},{"h":"جمالية التجاوب","x":"لا تتحقق ما لم تكن هناك فجوة بين ما يعرفه القارئ وما يفاجئه به النص."},{"h":"تفاوت المسؤولية","x":"القراءة في الكتب العلمية أسهل، وفي الكتب الفلسفية والأدبية أشق."}]},{"t":"المثابرة","pg":54,"key":"إن كثيراً من الناس لا يحتاج إلا إلى الشرارة الأولى حتى يبدأ مسيرة القراءة","p":["أن أهم عامل في النتائج التي سنحصل عليها هو كمية الجهد ومقدار الوقت الذي نبذله في سبيل تحقيقها والوصول إليها"],"items":[{"h":"صبر لا ينفد","x":"الذين أنجزوا إنجازات عظيمة تحلوا بصبر لا يعرف النفاد وعزيمة لا تعرف الانثناء."},{"h":"القراءة عبادة","x":"اعتقاد المسلم أنه في عبادة ما دام يقرأ نافعاً يدفعه إلى روح الدأب."},{"h":"أديسون","x":"سئل عن العبقرية فقال: 1% إلهام و99% عرق جبين."}]},{"t":"المرونة الذهنية","pg":55,"key":"القارئ الجيد يتمتع بقابلية جيدة لاستيعاب الجديد، ويمتلك بنية عقلية متفتحة، تقبل التحوير، وتستفيد من المراجعة.","p":["بل إن القارئ الممتاز يكون مستعداً لأن يستفيد من القراءة ما يمكنه من هدم بعض ما كان يظنه ثوابت فكرية، وإنشاء ثوابت جديدة"],"items":[{"h":"البرمجة الأولى","x":"التربية والبيئة تبني العقلية، وقد تكون برمجتها الأولى خاطئة أو قاصرة."},{"h":"النمو المعرفي","x":"دمج الجديد في الأنساق المستقرة وتوسيع أطر الفهم هو المعنى العميق للنمو المعرفي."}]},{"t":"الاستجابة لنبض العصر","pg":56,"key":"أن المواد التي نقرؤها أشبه بالغذاء، ومن الغذاء ما هو سام","p":["في اعتقادي أن القارئ الجيد، يحاول أن يقرأ للمبدعين في تخصصاتهم؛ فمن ينابيعهم يغرف الألوف من الكتّاب المتوسطين، والأفضل أن يشرب المرء من النبع مباشرة، فالقنوات التي يمر بها الماء قد تغير طعمه، وقد تفسده."],"items":[{"h":"الحديث والأصيل","x":"كتب حديثة في العلوم التجريبية، مع أمهات الكتب والمعاجم والشعر والقص البارع."},{"h":"كتب تحذر منها","x":"كتب بنيت على معطيات ناقصة، أو تحمل روحاً عنصرية، أو تقوم على التزوير العلمي."},{"h":"لا انفتاح مطلق","x":"الاستجابة للعصر لا تعني قراءة كل ما هب ودب، بل الوعي بالمعرفة التي يحتاجها مسلم اليوم."}]},{"t":"أنواع الكتب","pg":61,"key":"وهو نوع لا ينضب محتواه، وكلما عدت إليه شعرت أنه ينمّيك، وكأنه ينمو معك","p":["هذا النوع من الكتب، هو الذي يتطلّب من الإنسان أن يُقرأ على نحو مستمر، حتى يؤهل نفسه للارتقاء إلى مستواه"],"items":[{"h":"كتب يعاد إليها","x":"أمهات المراجع والموسوعات والمعاجم والشروح الكبرى، يرجع إليها عند الحاجة."},{"h":"كتب تقرأ مرة","x":"أكثر الكتب لا تحتاج مهارة عالية، ممتعة لكنها لا ترفع الفهم، فتقرأ بسرعة."},{"h":"كتب تؤخذ كلها","x":"تحتاج قراءة بطيئة ثم توضع على الرف، ولا تزيد على 5% مما في الأسواق."},{"h":"كتب تستحق عودة","x":"يرتقي فهم القارئ بها، فإذا عاد إليها لم يجد ما كان يؤمله."},{"h":"الكتاب النادر","x":"لا يشكل واحداً من عشرة آلاف، وأعلاه القرآن الكريم الذي لا تنقضي عجائبه."},{"h":"قراء عظماء","x":"عظماء الكتّاب قرؤوا القليل من الكتب لكن قرؤوه بشكل جيد."}]}],"quiz":[{"q":"ما الذي تعنيه القراءة التحليلية فوق مجرد الاطلاع والاستفادة؟","o":["الارتقاء بالقارئ إلى أفق الكاتب","إنهاء الكتاب في أقصر وقت ممكن","حفظ أهم عبارات الكتاب وفقراته","استخراج ما يخدم موضوعاً واحداً بعينه"],"why":"فهي لا تعني الاطلاع والاستفادة فحسب، بقدر ما تعني نوعاً من الارتقاء بالقارئ إلى أفق الكاتب الذي يقرأ له","pg":49},{"q":"يستشهد المؤلف بقول أديسون في العبقرية ليؤكد سمة من سمات القارئ الجيد، فما هي؟","o":["المثابرة وبذل الجهد","انتظار الومضات الذهنية","هدم الثوابت الفكرية","متابعة كتب العصر الحديثة"],"why":"أن أهم عامل في النتائج التي سنحصل عليها هو كمية الجهد ومقدار الوقت الذي نبذله في سبيل تحقيقها والوصول إليها","pg":54},{"q":"لماذا ينصح المؤلف بالقراءة للمبدعين في تخصصاتهم بدل الاكتفاء بالكتّاب المتوسطين؟","o":["لأن الشرب من النبع مباشرة أفضل من القنوات","لأن كتب المبدعين أسهل قراءة وأقل تكلفة","لأن كتبهم أحدث ما في الأسواق من مؤلفات","لأن قراءتهم تغني تماماً عن الشروح والمراجع"],"why":"والأفضل أن يشرب المرء من النبع مباشرة، فالقنوات التي يمر بها الماء قد تغير طعمه، وقد تفسده.","pg":56},{"q":"كم يقدّر المؤلف حجم الكتب التي يشعر قارئها بعد قراءة بطيئة أنه أخذ كل ما فيها؟","o":["لا يزيد على 5% مما يطرح","نحو 70% مما يطرح في السوق","واحد من عشرة آلاف كتاب","نحو 20% مما يطرح في السوق"],"why":"ويمكن القول: إن هذا النوع من الكتب لا يشكل أكثر من 5% مما هو مطروح في الأسواق من كتب.","pg":60},{"q":"ما الذي يميز النوع الأخير النادر جداً من الكتب عن سائر الأنواع؟","o":["أنه لا ينضب محتواه وكأنه ينمو مع قارئه","أنه يقرأ مرة واحدة ثم يوضع على الرف نهائياً","أنه يرجع إليه طالب العلم عند الحاجة","أنه يشعر قارئه أنه أخذ كل ما فيه"],"why":"وهو نوع لا ينضب محتواه، وكلما عدت إليه شعرت أنه ينمّيك، وكأنه ينمو معك","pg":61}],"scene":{"t":"فكرة تخالف قناعتي","x":"معلم يقرأ كتاباً تربوياً رصيناً فيجد فيه بالدليل ما يخالف أسلوباً في التدريس كان يظنه صواباً لا يناقش.","opts":["يزن الفكرة بمرونة ويعدل قناعته إن تبين له خطؤها","يترك الكتاب كله لأنه خالف ما اعتاده","يقبل كل ما في الكتاب لأنه جديد"],"why":"بل إن القارئ الممتاز يكون مستعداً لأن يستفيد من القراءة ما يمكنه من هدم بعض ما كان يظنه ثوابت فكرية، وإنشاء ثوابت جديدة","pg":55},"rel":[{"b":"jeel","ci":7,"t":"الفوضى المعرفية وترتيب المنهجية العلمية"}]},{"k":"c6","t":"مبادئ وقواعد وتساؤلات مهمة","q":"ما القواعد والأسئلة التي تجعل القراءة التحليلية أعمق؟","essence":"تفكير ولغة ومصادر وأسئلة تختبر الفهم","kw":["التفكير","المصطلح","التلخيص"],"sections":[{"t":"بين الفكرة والكلمة","pg":62,"key":"إن بين (الفكرة) التي يعبّر عنها الكاتب، وبين (الكلمة) التي يستخدمها لتوصيلها مسافةً ما قد تكون طويلة، وقد تكون قصيرة","p":["مما يجعل القراءة الحقّة ليست نوعاً من الاطلاع، وإنما نوعاً من الاكتشاف"],"items":[{"h":"مهمتان","x":"مهمة الكاتب أن يوصل المعاني، ومهمة القارئ تلقيها والاستفادة منها."},{"h":"أدوات القارئ","x":"الملاحظة الحادة والذاكرة المهيأة والخيال الخصب والذهن المتمرس حتى يلتقي بالكاتب في وسط الطريق."}]},{"t":"القراءة والتفكير","pg":63,"key":"فالقراءة ليست بديلة عن التفكير","p":["وأعتقد أن القارئ كلما كثرت قراءاته، وتضخم حجم المعلومات التي بين يديه، ازدادت حاجته إلى التفكير."],"items":[{"h":"ثلث ساعة","x":"من قرأ ساعة قراءة تحليلية فليخصص ثلث ساعة على الأقل للتأمل وربط ما قرأه بامتداداته."}]},{"t":"اللغة والمصطلح","pg":64,"key":"ولذا فاللغة ناقل غير جيد وغير شفاف","p":["فاللغة كائن مبدع، والإبداع هو سر عظمتها"],"items":[{"h":"المعنى والسياق","x":"إذا تعددت معاني الكلمة اعتمد القارئ على السياق وتذوقه الخاص للغة."},{"h":"لغوي واصطلاحي","x":"كلمة (عامل) عند النحوي غيرها عند المهندس، و(مشهور) و(صحيح) لها اصطلاح خاص عند عالم الحديث."},{"h":"آلية الفهم","x":"النصوص العقدية والفقهية والقانونية أقرب إلى الحرفية، والأدبية والفلسفية تزجي المعنى ولا تسجنه."}]},{"t":"المصادر والمعاجم","pg":66,"key":"ومعرفة عدد محدود من المراجع ولو واحداً خير من لا شيء.","p":["لا شك أن هذا شاق، لكن ما دام الهدف هو المزيد من الفهم والعمق المعرفي، فيجب دفع الثمن عن طيب خاطر."],"items":[{"h":"تاريخ العلم","x":"لا نفهم أي علم حتى نفهم تاريخه، فيحسن الاطلاع على كتابين أو ثلاثة في تاريخه."},{"h":"الموسوعات والمعاجم","x":"يستحسن في مكتبة كل طالب علم ثلاثة معاجم: صغير ومتوسط وكبير."},{"h":"الشروح التراثية","x":"بعض الكتب ظفر بأكثر من عشرين شرحاً، وألفية ابن مالك ظفرت بنحو 127 شرحاً."}]},{"t":"تفلية الكتاب","pg":68,"key":"إن القراءة التحليلية الجيدة، تعني نوعاً من (التفلية) للكتاب، ومحاولة إضفاء نوع من التنظيم على محتواه الداخلي من أجل تسهيل استيعابه.","p":["لكن هذا ليس متوفراً في كثير من الكتب الجيدة، مما يعني أن على القارئ أن يفعل ذلك من أجل إيجاد نوع من إيجاد التصور المنطقي المتسلسل لمسائل الموضوع"],"items":[{"h":"إشارات القارئ","x":"خط تحت الجمل المهمة، وخط شاقولي في الهامش، ونجمة، ودائرة بقلم الرصاص، والقلم المظهر، وقصاصات الورق."},{"h":"أسئلة على الهامش","x":"تسجيل أسئلة على ما أورده المؤلف أو الإجابة عن أسئلته أو عرض رأي مغاير."},{"h":"الغاية","x":"أن تعكس الإشارات اهتمام القارئ وردود فعله لفائدته وفائدة من يقرأ الكتاب بعده."}]},{"t":"تساؤلات مهمة","pg":70,"key":"والسؤال الذي على القارئ أن يطرحه على نفسه: هل أنا من الشريحة التي يستهدفها المؤلف، ويوجِّه إليها خطابه؟","p":["سيكون من واجب كل قارئ حريص على أن ينفذ إلى أعماق النص، ويوسع فهمه عن طريق قراءته؛ أن يعمد إلى توجيه عدد من الأسئلة قبل قيامه بشراء الكتاب وأثناء قراءته، وبعد الفراغ منها."],"items":[{"h":"الشريحة","x":"كتاب لم يوجه إليك قد لا ينفعك، وأسوأ منه كتاب يمس مقدساتك فلا يورثك سوى الحنق والمرارة."},{"h":"هوية الكتاب","x":"جنسه المعرفي ومذهبه، أهو سرد أم احتجاج، وما أفكاره الأساسية والهامشية."},{"h":"اختبار الفهم","x":"أداتان: الإتيان بأمثلة على أفكار الكاتب، وتلخيص ما قرئ بأسلوب القارئ الخاص."},{"h":"أسئلة الكاتب الجيد","x":"الكاتب الجيد يقدم حلولاً ويثير إشكالات جديدة، فيسأل القارئ عن مدى إقناعه وجدية أسئلته."}]}],"quiz":[{"q":"ما الذي يقرره المؤلف عن العلاقة بين القراءة والتفكير؟","o":["أن القراءة ليست بديلة عن التفكير","أن كثرة القراءة تغني عن التأمل","أن التفكير يكون قبل القراءة فقط","أن التأمل مطلوب في الكتب الأدبية وحدها"],"why":"فالقراءة ليست بديلة عن التفكير","pg":63},{"q":"لماذا يصف المؤلف اللغة بأنها ناقل غير جيد وغير شفاف؟","o":["لأن تجددها وتوسعها جعلا الإحاطة بها مستحيلة","لأن ألفاظها جامدة لا تفي بالحاجات المتجددة","لأن الكتّاب يتعمدون الإغراب والالتواء دائماً","لأن مصطلحاتها واحدة المعنى في كل العلوم"],"why":"كل ذلك جعل إمكانية الإحاطة بها والتمكن من متابعة تجديداتها أمراً مستحيلاً، يواجهه كل متعامل معها، مهما أوتي من مهارة وخبرة","pg":64},{"q":"قارئ أنهى نصاً قانونياً ثم بدأ نصاً أدبياً غنياً بالظلال. كيف ينبغي أن يتعامل مع الثاني؟","o":["برحابة فكرية وخيال خصب لأنه يزجي المعنى","بحرفية تامة ودقة لأن كل لفظ فيه محسوب","بالبحث عن المدلول الاصطلاحي لكل كلمة","بحفظ عباراته لأن جمالها أهم من معانيه"],"why":"ويجب أن نتعامل معها برحابة فكرية وخيال خصب، وإلا قد لا يكون نصيبنا منها أكثر من سوء الفهم!","pg":66},{"q":"بمن يشبّه المؤلف من يقرأ في علم وهو لا يعرف تاريخه؟","o":["بمن فتح عينيه في غرفة لا يدري أين هي","بمن يبحث عن إبرة في كومة من القش","بمن يشرب من قنوات غيرت طعم الماء","بمن يقرأ كتاباً لم يوجه إليه خطابه"],"why":"وإن الذي لا يعرف تاريخ العلم الذي يقرأ فيه أشبه بمن فتح عينيه في غرفة، لا يدري إلى أي حي، ولا إلى أي مدينة تنتمي","pg":67},{"q":"أي مما يلي يجمع أداتي اختبار الفهم اللتين يقترحهما المؤلف؟","o":["الإتيان بأمثلة على الأفكار وتلخيصها بأسلوب القارئ","ترديد عبارات الكاتب بنصها ثم حفظ أجملها","وضع خطوط تحت الجمل ونجمة بجانب المهم منها","قراءة المقدمة والفهرس والمراجع قبل البدء في الكتاب"],"why":"الأولى: أن يحاول القارئ أن يأتي بأمثلة وملاحظات على القواعد والأفكار والملاحظات التي يثيرها الكاتب","pg":73}],"scene":{"t":"نسيت اسم المؤلف","x":"معلم قرأ كتاباً قبل شهر، وحين سأله زميل عنه لم يتذكر اسم مؤلفه ولا فكرته الأساسية.","opts":["يسأل نفسه أثناء القراءة عن هوية الكتاب وأفكاره ويعبر عنها بإيجاز","يعيد قراءة الكتاب كله بسرعة أكبر","يكتفي بما بقي في ذهنه من انطباع عام"],"why":"كلما استطاع القارئ أن يعبّر عن هذه الأسئلة على نحو دقيق وموجز كانت فائدته مما يقرأ أعظم.","pg":72}},{"k":"c7","t":"الحوار مع الكاتب","q":"كيف نحاور الكاتب وننقده بإنصاف؟","essence":"فهم أولاً ثم نقد محدد معلل","kw":["الحوار","النقد","الإنصاف"],"sections":[{"t":"النفق من جهتين","pg":76,"key":"وحين يصل الكتاب إلى يد القارئ تكون وظيفة المؤلف قد انتهت؛ حيث إنه حفر الجزء الذي يليه من النفق، وعلى القارئ أن يحفر من جهته الجزء المتبقي حتى يصبح اللقاء ممكناً.","p":["فالكلمة الأخيرة ليست كلمة المؤلف، وإنما هي كلمة القارئ"],"items":[{"h":"حياة الكتاب","x":"الكتاب لا يحيا ولا يبلغ أهدافه إلا بالقارئ، فموقفه حيوي للغاية."},{"h":"بداية الحوار","x":"تبدأ من المؤلف، فعليه أن يقنع قارئه بأن كتابه جيد يستحق القراءة والنقد."}]},{"t":"البداية الصحيحة للقارئ","pg":76,"key":"فسوء الفهم ليس حادثاً نادراً","p":["وحين يعلن قارئ أنه لم يفهم ما قاله الكاتب، فإنه يكون قد حمى نفسه من الفهم الخاطئ"],"items":[{"h":"لا خلاف قبل الفهم","x":"لا يبدأ الحوار ولا يتخذ موقفاً مخالفاً قبل أن يتأكد من فهمه الجيد."},{"h":"سر الكتب الجيدة","x":"فيها ما يستعصي على فهم بعض القراء، وفيها جديد يثير الجدل فيحفز الحوار."}]},{"t":"نوعان سيئان من القراء","pg":77,"key":"وإن نقد الكتاب، ومحاولة العثور على وجهة نظر أخرى غير وجهة نظر المؤلف دليل قوي على أن تقدماً ما قد حدث لدى القارئ","p":["نوع يقرأ قراءة المستسلم للكاتب المعتقد بصواب ما يقوله؛ ولذا فإنه يتلقّى ما يقرأ كما تُتلقى البدهيات واليقينيات"],"items":[{"h":"المستسلم","x":"عليه أن يدرك أن الكاتب قد يعبر عن تجربة ناقصة أو هوى أو تعصب أو مكسب مادي."},{"h":"لا كتاب بلا خطأ","x":"ليس هناك كتاب جيد، حاشا كتاب الله، لا يحتمل النقد والمراجعة والتحسين."},{"h":"المشاكس","x":"همه الثغرات، يستعجل ويقرأ بعين واحدة، وتناقل المعرفة عنده مشاحنة."}]},{"t":"النقد تقييم شامل","pg":79,"key":"إن النقد نوع من التثمين والتقييم الشامل للمنتج المعرفي وتحديد موقف جلي منه.","p":["وفي كل الأحوال فلا ينبغي أن يفهم الحوار مع الكاتب على أنه تتبع للهفوات والنواقص"],"items":[{"h":"مساحات الجمال","x":"كشف الجمال والإضافات الجديدة في النص لا يقل أهمية، وكثيراً ما يكون أشق من معرفة الأخطاء."},{"h":"التيار والمذهب","x":"معرفة التوجه العام للكاتب تحجز القارئ عن إصدار حكم مبتسر غير ناضج."},{"h":"الكاتب ينمو","x":"لا يصدر حكم نهائي على الكاتب من كتاب واحد إلا إذا كان آخر كتبه."}]},{"t":"مساقات للنقد","pg":81,"key":"لتلافي ذلك، فإننا نرى أن نقد القارئ ينبغي أن يكون محدداً ومفصلاً ومعلّلاً","p":["إن كثيراً من الكتّاب، لا يكتفون بعرض وجهات نظرهم حيال الموضوع الذي يعالجونه، بل يسعون إلى إقناع القارئ بوجهة نظرهم، وهذا شيء مشروع"],"items":[{"h":"الخطابة بدل الدليل","x":"بعض الكتّاب يلجأ إلى البيان والخطابة بعيداً عن الإحصاءات، كقائد يحمس جيشاً لم يتدرب."},{"h":"الصحة والدليل","x":"القاعدة البحثية: إن كنت ناقلاً فالصحة، وإن كنت مدعياً فالدليل."},{"h":"عوامل مهملة","x":"كمقال يرى أن العالم الإسلامي لا يعاني أزمة سكانية لوجود أراض بور، ويهمل عوامل الماء والاستصلاح والحدود."},{"h":"البديل","x":"المهم أن يوضح الناقد ما كان على الكاتب أن يفعله، فنكون قد أعدنا إنتاج الكتاب."}]}],"quiz":[{"q":"ما الصورة التي يستعملها المؤلف لوصف العلاقة بين الكاتب والقارئ؟","o":["نفق يحفره كل منهما من جهته","جسر يبنى من ضفة واحدة فقط","سباق يصل فيه الكاتب أولاً","نبع يشرب منه القارئ مباشرة"],"why":"حيث إنه حفر الجزء الذي يليه من النفق، وعلى القارئ أن يحفر من جهته الجزء المتبقي حتى يصبح اللقاء ممكناً.","pg":76},{"q":"متى يحق للقارئ أن يبدأ الحوار ويتخذ موقفاً مخالفاً للكاتب؟","o":["بعد أن يتأكد أنه فهم الكتاب جيداً","فور عثوره على أول ثغرة في الكتاب","بعد قراءة المقدمة والفهرس وحدهما","حين يخالف الكتاب ما يعتقده سلفاً"],"why":"وذلك بألا يبدأ الحوار واتخاذ موقف مخالف قبل أن يتأكد من أنه فهم الكتاب على نحو جيد","pg":76},{"q":"قارئ لا يهمه من الكتاب إلا العثور على الثغرات والهفوات. كيف يصفه المؤلف؟","o":["قارئ مشاكس يقرأ بعين واحدة","قارئ مستسلم يتلقى البدهيات","قارئ ممتاز يراجع ثوابته","قارئ متمرس له ذائقة معرفية"],"why":"إنه قارئ (مشاكس) وتناقل المعرفة لديه ليس أكثر من مشاحنة!","pg":79},{"q":"لماذا لا ينبغي إصدار حكم نهائي على كاتب من خلال كتاب واحد قرأناه له؟","o":["لأن الكاتب الجيد ينمو ويتخلى عن بعض أفكاره","لأن الكتاب الواحد لا يكون موجزاً بطبيعته","لأن النقد لا يصح إلا بعد قراءة كل كتب التيار","لأن أعظم الكتب لا يستطيع أحد أن يحط منها"],"why":"فالكاتب الجيد ينمو باستمرار، وخلال نموه يتخلى عن بعض الأفكار، ويؤمن بأفكار جديدة","pg":80},{"q":"لاحظ قارئ أن كاتباً نقل أرقاماً بلا توثيق وادعى رأياً جديداً بلا برهان. ما القاعدة البحثية التي يحتكم إليها؟","o":["إن كنت ناقلاً فالصحة، وإن كنت مدعياً فالدليل","العهدة على الراوي في كل ما ينقله من الأخبار والأرقام","الكلمة الأخيرة كلمة القارئ لا كلمة المؤلف","أعظم الكتب يمكن أن يحط منها أضعف القراء"],"why":"والقاعدة البحثية العامة في هذا الشأن، هي: «إن كنت ناقلاً فالصحة، وإن كنت مدعياً فالدليل»","pg":82}],"scene":{"t":"نقد كتاب تربوي","x":"معلم قرأ كتاباً تربوياً مشهوراً فوجد فيه مبالغات وحماسة خطابية، وطلب منه أن يكتب عرضاً نقدياً له لزملائه.","opts":["يكتب نقداً محدداً مفصلاً معللاً يبين فيه ما كان على الكاتب أن يفعله","يكتب أن الكتاب ضعيف ومعلوماته ناقصة دون تفصيل","يتجاهل المبالغات لأن الكتاب مشهور ومؤلفه كبير"],"why":"المهم في كل نقد يوجَّه لأي كتاب أو كاتب أن يوضح ما الذي كان على الكاتب أن يفعله","pg":84}},{"k":"c8","t":"القراءة المحورية","q":"كيف نقرأ لخدمة موضوع واحد نتعمق فيه حتى نصير مرجعاً؟","essence":"تخصص منفتح يبني موضوعاً بأسئلة محددة","kw":["التخصص","البحث","هيكل الموضوع"],"sections":[{"t":"زمن التخصص","pg":86,"key":"إن التقدم الرأسي في العلم يتطلب التخصص الدقيق، وتركيز الفكر والخبرة والبحث في بؤرة معرفية ضيقة، حتى يمكن الوصول إلى شيء جديد ذي قيمة.","p":["إن التخصص هو أن يبني الإنسان معرفة مدققة في موضوع ما مكتفياً بالمعرفة العامة في باقي الموضوعات"],"items":[{"h":"نهاية العالم الموسوعي","x":"من المتعذر اليوم أن يستمر نمط العالم الذي يلم بعلوم عصره."},{"h":"متخصص منفتح","x":"لا يريد المؤلف متخصصاً منغلقاً، بل منفتحاً على التخصصات التي تتبادل التأثير."},{"h":"مثال العربية","x":"ينتفع متخصص العربية بالساميات والأسلوبية والمنطق وعلوم النفس والاجتماع والتاريخ."},{"h":"الدقة والاتساع","x":"بين العمق والاتساع جدلية رائعة تولد طاقة استبصارية هائلة."}]},{"t":"ما القراءة المحورية؟","pg":88,"key":"القراءة المحورية، هي تلك القراءة التي تستهدف الوقوف على معلومات وأفكار ومفاهيم، تتعلق بموضوع معين، كما يفعل باحث أراد أن يكتب في موضوع ما","p":["ولذا فقد لا يقرأ القارئ قراءة محورية سوى فصل أو باب أو صفحة من كتاب، ويتجاوز الباقي."],"items":[{"h":"مقارنة بالتحليلية","x":"التحليلية تستهدف تملك ما في الكتاب وفقهه، والمحورية تستخرج ما يخدم الموضوع."}]},{"t":"البداية والخطوة الأولى","pg":89,"key":"ولذا فإن ما يلمع في الذهن، لا يفيد أكثر من أنه فتحٌ لباب أو بناء لرأس جسر، وبعد ذلك علينا أن نختبر واقعة ذلك.","p":["الخطوة الأولى: في القراءة المحورية، تتلخص في أن يطلع القارئ على الكتب والمراجع التي تعرض الأدبيات العامة للعلم الذي ينتمي إليه الموضوع"],"items":[{"h":"حدس محدود","x":"قد يتبين أن الموضوع قتل بحثاً أو أنه ضئيل لا يستحق العناء."},{"h":"الوصول إلى الكتب","x":"فهارس المكتبات، ومسارد المراجع، وسؤال المختصين."},{"h":"قراءتان","x":"تفحصية سريعة لتحديد الموضوع، ثم ثانية لاستبعاد ما لا يخدمه واستخراج النصوص إلى بطاقات."}]},{"t":"الخطوتان الثانية والثالثة","pg":92,"key":"حين تتم صياغة هذه الأسئلة وأشباهها على نحو واضح، فإن ذلك يعني أن هيكل البحث صار واضحاً","p":["الخطوة الثالثة: وتتمثل في توزيع النصوص التي اخترناها على الأسئلة التي استطعنا بَلْوَرتها"],"items":[{"h":"الخطوة الثانية","x":"قراءة تحليلية للفصول والنصوص اللصيقة بالموضوع، دون نقل نصوص كثيرة لا حاجة إليها."},{"h":"مثال البطالة","x":"تعريفها وحجمها وجذورها وأسبابها وآثارها والمسؤول عنها وعلاجها وتكاليفه ومدته وعقباته."},{"h":"الشفافية","x":"التقاط الأجوبة من نصوص بعيدة، وترجمتها فكرياً ثم سبكها بلغة الباحث ونسقه."},{"h":"نص قيم في كتاب تافه","x":"قد يعثر المرء على نص قيم جداً في كتاب تافه، والقراءة الانتقائية تتكفل به."},{"h":"الاستقلال","x":"الفطنة تحرر الباحث من التبعية لمراجعه، فالأفكار قد تستخدم ضد منتجيها في سياق مغاير."}]},{"t":"دعوة إلى الشباب","pg":96,"key":"إن أصعب نقطة هي البداية، لكن لنكن على ثقة أننا سندهش من أنفسنا عندما ننطلق!","p":["إن الأمر يحتاج إلى الالتزام التزاماً جاداً ودقيقاً بقراءة ساعتين يومياً مدة خمس سنوات على نحو متواصل"],"items":[{"h":"مطالعات هادفة","x":"على الشاب المسلم أن يجعل جل مطالعاته مخصصة لخدمة موضوع بعينه."},{"h":"العائقان","x":"ضعف الوعي والكسل يقعدان كثيراً من المتعلمين عن البحث، ويمكن جعل البيوت وحدات بحث مصغرة."},{"h":"مرجع في خمس سنوات","x":"شاب متوسط الذكاء يمكنه أن يصبح حجة في موضوع مثل فقه الزكاة أو القياس."}]}],"quiz":[{"q":"ما الفرق الجوهري بين القراءة التحليلية والقراءة المحورية؟","o":["الأولى لتملك الكتاب والثانية لاستخراج ما يخدم موضوعاً","الأولى سريعة جداً والثانية بطيئة في كل الكتب","الأولى للمتخصصين والثانية لعامة القراء وحدهم","الأولى لكتب التاريخ والثانية لكتب الفقه والأدب والفلسفة"],"why":"أما في القراءة المحورية فإن الاطلاع على كتاب ما لا يسعى إلى ذلك على نحو أساسي، وإنما يسعى إلى استخراج ما يخدم الموضوع الذي يستهدف القارئ بناءه","pg":88},{"q":"لمع في ذهن طالب عنوان يظنه جديراً بالبحث. ما قيمة هذه الفكرة عند المؤلف؟","o":["فتح لباب يحتاج إلى اختبار واقعه","دليل كافٍ على أن الموضوع جديد","علامة أن الموضوع قتل بحثاً","هيكل جاهز يبنى عليه البحث"],"why":"ولذا فإن ما يلمع في الذهن، لا يفيد أكثر من أنه فتحٌ لباب أو بناء لرأس جسر، وبعد ذلك علينا أن نختبر واقعة ذلك.","pg":89},{"q":"ما الخطوة الثانية في القراءة المحورية؟","o":["قراءة النصوص اللصيقة بالموضوع تحليلياً","الاطلاع على الأدبيات العامة لعلم الموضوع","توزيع النصوص المختارة على الأسئلة","سؤال المختصين عن المراجع المناسبة"],"why":"الخطوة الثانية: وتتمثل في قراءة الفصول والمقاطع والنصوص التي يرى أنها لصيقة بموضوعه، ويجب أن تكون القراءة هذه المرة تحليلية","pg":91},{"q":"باحث وجد أجوبة أسئلته كلها جاهزة عند عدد من الكتّاب. ماذا يعني ذلك؟","o":["أنه لا مشكلة لديه ولا إضافة قيمة","أن بحثه صار جاهزاً مكتمل الأدلة","أن مصادره موثوقة لا تحتاج نقداً","أن هيكل بحثه صار واضحاً تماماً"],"why":"وحين يجد القارئ أجوبة أسئلته لدى كاتبين أو ثلاثة أو عشرة، فهذا يعني أنه ليس لديه مشكلة سيتولى حلها، أو إضافة معرفية قيّمة","pg":93},{"q":"ما الذي يراه المؤلف كافياً ليصبح شاب متوسط الذكاء مرجعاً في موضوع محدد؟","o":["ساعتان يومياً مدة خمس سنوات متواصلة","كتاب كل أسبوع في موضوعات متنوعة","التفرغ التام وتعطيل علاقاته","حفظ متن واحد بشروحه عشر سنوات"],"why":"إن الأمر يحتاج إلى الالتزام التزاماً جاداً ودقيقاً بقراءة ساعتين يومياً مدة خمس سنوات على نحو متواصل","pg":96}],"scene":{"t":"بحث عن البطالة","x":"طالب جامعي كلف ببحث عن البطالة في بلده، فجمع عشرات الكتب ولا يعرف من أين يبدأ.","opts":["يصوغ أسئلة واضحة تغطي الموضوع ثم يوزع عليها النصوص المختارة","يقرأ كل مصادره بتمعن بالغ وينقل منها نصوصاً كثيرة","يكتب مما يعرفه ثم يبحث عن مراجع تؤيده"],"why":"حين تتم صياغة هذه الأسئلة وأشباهها على نحو واضح، فإن ذلك يعني أن هيكل البحث صار واضحاً","pg":92}},{"k":"c9","t":"قراءة كتاب في التاريخ (نموذجاً)","q":"ماذا يحتاج قارئ كتب التاريخ ليفهمها بوعي وإنصاف؟","essence":"التاريخ اجتهاد مؤرخ يقرأ بوعي وحذر","kw":["علم التاريخ","الانتقائية","الموضوعية"],"sections":[{"t":"الخلفية المعرفية","pg":98,"key":"ولهذا كله نرى أن معرفة القارئ بتاريخ العلم الذي يقرأ فيه، وبطبيعته ومشكلاته الحقيقية، ستعود عليه ببصيرة معرفية لا تقدر بثمن","p":["وقد اخترت أن أقدم للقارئ الكريم هذه الخلفية عن (علم التاريخ) لما له من أثر خطير في حياة الناس"],"items":[{"h":"الانطباعات الخاطئة","x":"معظم الكتب لا تمنحنا رؤية عن نوعية الأحكام في العلم ولا مصداقية تعميماته."},{"h":"مواقف متباينة","x":"قدس قوم التاريخ حتى جعلوه علم العلوم، وقال آخرون إنه لا يصلح أن يكون علماً."}]},{"t":"طبيعة علم التاريخ","pg":100,"key":"لكن بين التاريخ والجيولوجيا مفارقةٌ كبيرة، فالصخور شواهد محايدة، لكن وثائق التاريخ وثائق تتصل بمختلف جوانب حياة الناس، وكتبتها يد إنسان","p":["وقصور الصورة لا يعود إلى أن بعض أجزائها مفقود"],"items":[{"h":"علم نقد وتحقيق","x":"ليس كالفلك علم معاينة، ولا كالكيمياء علم تجربة، لكنه علم نقد وتحقيق."},{"h":"شبه بالجيولوجيا","x":"يرى هرنشو أن أقرب العلوم الطبيعية إليه الجيولوجيا، فكلاهما يستدل بآثار قليلة."},{"h":"صورة الصفوة","x":"من يكونون الصورة جزء من الصفوة، أما انطباع العامة فلا نعرفه."},{"h":"القاضي والمؤرخ","x":"القاضي مع الشهود لا يتأكد دائماً، فكيف بالمؤرخ تفصله مئات السنين؟"}]},{"t":"الانتقائية والاجتهاد","pg":102,"key":"الانتقاء الذي يقوم به المؤرخ يجعل البنيان التاريخي كله انتقائياً","p":["وما دام عمله اجتهادياً، فإنه إذن سيظل محتملاً للخطأ والصواب."],"items":[{"h":"ضرورة الاختيار","x":"تعدد الروايات وتضاربها يلزم المؤرخ بالاختيار، وإلا خنقه سيل الوقائع المجدبة."},{"h":"سد الثغرات","x":"يشعر المؤرخ بضرورة تقديم صورة كاملة فيسد الثغرات بسلسلة من الأحكام المقبولة."},{"h":"التعليل","x":"اخترعه اليونان لتلافي ثغرات الاستقراء الناقص، وهو عمل منطقي عقلي فلسفي."}]},{"t":"لماذا يختلف المؤرخون؟","pg":105,"key":"المؤرخ أيضاً ليس آلة تسجيل، بل هو في الأساس راوية، يقرأ الأحداث من أفق تجربته الخاصة، وخبرته الذاتية.","p":["مهما بلغ المؤرخ من العالمية، ومهما امتلك من النظرة الكونية للأمور والحوادث، فإنه في النهاية يظل ابن بيئته ومحيطه، ووليد لحظات زمانه المتغير."],"items":[{"h":"المزاج","x":"كان كارليل يعشق عظماء الرجال، وكان ويلز ينفر منهم ويكره مشاهير العسكريين."},{"h":"أهواء التحيز","x":"الانتماء لوطن أو عنصر أو مذهب، وأصعبه ما يتجلى في صورة مبدأ معلل مدعم بالحجج."},{"h":"قوة الأمة وضعفها","x":"مؤرخ الأمة القوية يكتب بروح التفاؤل، ومؤرخ الأمة المفككة يكتب بالتشاؤم والتلاوم."},{"h":"العامل الحاسم","x":"اختلفوا فيه: البيئة الطبيعية أم السلالة أم الاقتصاد أم البطولات أم المعتقدات، ونزع بعضهم إلى الأحادية."}]},{"t":"لا موضوعية مطلقة","pg":109,"key":"النتيجة التي يمكن أن ننتهي إليها من وراء كل ما سبق هي أنه ليس في أعمال المؤرخين موضوعية مطلقة","p":["لأن الفهم ليس مسألة سلبية، بل يتضمن الحكم على الأدلة بوساطة مبادئ، يفترض صحتها افتراضاً مستقلاً"],"items":[{"h":"المعاصرة","x":"المؤرخ المعاصر يعرف الأجواء، لكنه قد يخضع لضغوط أو يتأثر بالحسد والمنافسة."},{"h":"السياق","x":"نزع أي نص تاريخي من سياقه وبيئته يؤدي إلى سوء التعامل معه وسوء تقدير دلالته."},{"h":"ابن خلدون","x":"حكّم أصول العادة وطبائع العمران في الأخبار، فرد قصة العباسة مع جعفر البرمكي وحكاية تابوت الإسكندر."},{"h":"لا حط من التاريخ","x":"لم يرد المؤلف الحط من قدر التاريخ ولا المؤرخين، بل تكوين خلفية لقارئه."}]},{"t":"أسئلة حول المؤرخ","pg":119,"key":"ومع أن الحياد التام غير ممكن إلا أن محاولة الالتزام به لا بد لها أن تثمر درجة من الفصل بين الذات والموضوع.","p":["هل كان المؤلف حين كتب كتابه يمر بأزمة حادة، فيغلب على تصويره للوقائع روح التشاؤم، أو أنه يمر بحالة ازدهار وانتصار، فيغلب على عمله طابع الاستبشار والتفاؤل؟"],"items":[{"h":"الصبغة المذهبية","x":"كتب الطبقات تبالغ في الثناء على أبناء المذهب، فيعسر عليها تقديم رؤية متوازنة."},{"h":"البيئة","x":"أمغلقة يسود فيها التفكير النمطي أم مفتوحة؟ وهل رحل المؤلف أم هو محلي الثقافة؟"},{"h":"المسافة الواعية","x":"هل يفصل المؤرخ رأيه الشخصي عن الأحداث، أم يحلل الخبر وينقده ويتخذ موقفاً؟"},{"h":"المصادر","x":"هل هي موثوقة؟ وقد نقل الطبري عن متعصبين ومعتدلين وثقات، وقال لنا: العهدة على الراوي."},{"h":"التفاصيل","x":"التحريف والخلط يقعان في التفاصيل الدقيقة لا في الخطوط العريضة، فنلزم الحذر عندها."},{"h":"الخاتمة","x":"يختم المؤلف بأن ثمرة القراءة تزداد كلما نضج وعينا بما نريده منها وانتظم."}]}],"quiz":[{"q":"ما المفارقة الكبيرة التي يراها المؤلف بين التاريخ والجيولوجيا؟","o":["الصخور محايدة ووثائق التاريخ كتبها إنسان","الجيولوجيا علم معاينة والتاريخ علم تجربة","التاريخ يملك أدلة أكثر من الجيولوجيا","آثار الطبيعة أحدث من وثائق المؤرخين"],"why":"لكن بين التاريخ والجيولوجيا مفارقةٌ كبيرة، فالصخور شواهد محايدة، لكن وثائق التاريخ وثائق تتصل بمختلف جوانب حياة الناس، وكتبتها يد إنسان","pg":100},{"q":"كيف يصنف المؤلف علم التاريخ بين العلوم؟","o":["علم نقد وتحقيق","علم معاينة مباشرة","علم تجربة واختبار","علم العلوم جميعاً"],"why":"لكنه علم نقد وتحقيق.","pg":99},{"q":"لماذا يظل عمل المؤرخ عند المؤلف محتملاً للخطأ والصواب؟","o":["لأن انتقاءه يجعل عمله اجتهادياً","لأن الوثائق تختفي بمرور الزمن","لأن المؤرخين يحذفون الأسانيد","لأن الأحداث لا تتكرر أبداً"],"why":"وما دام عمله اجتهادياً، فإنه إذن سيظل محتملاً للخطأ والصواب.","pg":102},{"q":"يقول المؤلف إن المؤرخ مهما بلغ من العالمية يظل (ابن بيئته). ما المقصود؟","o":["أن زمانه ومكانه يقولبان فكره وتحليله","أنه لا يكتب إلا عن الأحداث في بلده","أنه يعتمد على رواة محليين وحدهم","أنه يكره مؤرخي البلدان الأخرى"],"why":"إن فكر البشر تجري قولبته من قبل البيئة الزمانية والمكانية، ولا يختلف في هذا الرجل البدائي عن الرجل المتمدن","pg":107},{"q":"على أي أساس رد ابن خلدون أخباراً مثل قصة العباسة مع جعفر البرمكي؟","o":["تحكيم طبائع العمران وأصول العادة","أن رواتها لم يعاصروا أحداثها أبداً","أن المسعودي نقلها بلا إسناد","أن الطبري أخذها عن المتعصبين"],"why":"وكثيراً ما وقع للمؤرخين والمفسرين وأئمة النقل المَغالِط في الحكايات والوقائع؛ لاعتمادهم فيها على مجرد النقل غثاً أو سميناً","pg":114}],"scene":{"t":"كتاب طبقات متحمس","x":"طالب يعد بحثاً عن علماء مذهب فقهي، فيجد كتاب طبقات يثني على كل أبناء المذهب ويذم مخالفيهم.","opts":["يسأل عن صبغة المؤلف المذهبية ويقرأ بحذر ويوازن بمصادر أخرى","يأخذ كل ما فيه لأن مؤلفه عالم كبير","يرفض الكتاب كله لأن مؤلفه متحيز"],"why":"إذا كان الأمر كذلك أو قريباً منه فإن من العسير جداً على المؤلف أن يقدم رؤية منصفة ومتوازنة للموضوع الذي يعالجه","pg":117}}],"highlights":[{"x":"فالمسألة ليست كمالية ولا ترفيهية، وإنما هي مسألة مصير.","pg":16},{"x":"إن الوقت هو المادة التي صُنعت منها الحياة","pg":24},{"x":"إن القراءة المثمرة تستحق منا التخطيط والتفكير والمثابرة والعناء، لأنها من أهم العوامل التي تعيد صياغة وجودنا من جديد!","pg":28},{"x":"إن مكاسبنا من وراء كتب تعطي معلومات كمكاسب شخص امتلك قطعة ذهبية، أما مكاسبنا من وراء كتب تحسّن الوضع الفكري لدينا، فهي مثل مكاسب من أُعطي مفتاح منجم من الذهب!","pg":34},{"x":"إن الكتاب مثل (القميص) كثيراً ما تكون جودته من مناسبته للابسه، وليست من جودة قماشه أو لونه.","pg":36},{"x":"وذلك لأن القراءة عمل عقلي، يبدأ بالنظر.","pg":44},{"x":"أن المواد التي نقرؤها أشبه بالغذاء، ومن الغذاء ما هو سام","pg":56},{"x":"عظماء الكتّاب كانوا دائماً قرّاء عظماء، قرؤوا القليل من الكتب، لكن قرؤوه بشكل جيد.","pg":62},{"x":"فالقراءة ليست بديلة عن التفكير","pg":63},{"x":"فالكلمة الأخيرة ليست كلمة المؤلف، وإنما هي كلمة القارئ","pg":76},{"x":"وكلما تمكنا من فعل ذلك أثبتنا أننا لم نقرأ الكتاب فحسب، وإنما أعدنا إنتاجه من جديد.","pg":84},{"x":"إن أصعب نقطة هي البداية، لكن لنكن على ثقة أننا سندهش من أنفسنا عندما ننطلق!","pg":96}],"concepts":[{"term":"البرمجة الثقافية","def":"إن العقل البشري، يميل دائماً إلى تكوين عادات ورسم أطر لعمله، وهي مع مرور الوقت تشكل نوعاً من البرمجة له.","pg":10},{"term":"شيخوخة المعلومات","def":"إن تقادم المعلومات يتجلى في صور شتى، فتارة في ظهور زيفها أو عدم دقتها، وتارة يتجلى في عدم ملاءمتها للخطط الجديدة","pg":11},{"term":"الساعة الذهبية","def":"أن نكتشف (الساعة الذهبية) في يومنا، حيث يكون الواحد منا في قمة نشاطه","pg":25},{"term":"القراءة الاكتشافية (التصفحية)","def":"ما لم نلقِ عليه نظرة تصفحية، لنكتشف مدى حاجتنا إليه، والطريقة التي علينا أن نتبعها في قراءته.","pg":36},{"term":"القراءة السريعة","def":"وتقوم فكرة القراءة السريعة على ما هو معلوم من أن النظر يقفز من مساحة إلى أخرى","pg":40},{"term":"النكوص","def":"مشكلة القارئ غير المتمرس، هي (النكوص) إلى سطور سابقة","pg":40},{"term":"القراءة الانتقائية","def":"حين يتجه المرء إلى التعمق في موضوع بعينه، فإنه يكون بحاجة إلى تتبع العديد من المراجع والكتب المتنوعة للعثور على مادة متجانسة","pg":45},{"term":"القراءة التحليلية","def":"إن القراءة التحليلية هي أفضل أسلوب يمكن للمرء أن يتبعه في استكناه مضمون كتاب ما في وقت غير محدد.","pg":49},{"term":"جمالية التجاوب","def":"وصار يعتقد أن (جمالية التجاوب) لن تتحقق ما لم يكن هناك فجوة بين ما يعرفه القارئ وبين ما يفاجئه به النص من انزياح عن خبرته","pg":51},{"term":"النص الجيد","def":"إن النص الجيد هو النص الذي يشتمل على فراغات معرفية، وملء هذه الفراغات من الآن فصاعداً صار من مهمة القارئ الجيد","pg":52},{"term":"الاستجابة لنبض العصر","def":"لكنها تعني الوعي بالمعرفة التي يحتاجها مسلم اليوم، ليعيش زمانه بكفاءة وفاعلية","pg":58},{"term":"التفلية","def":"إن القراءة التحليلية الجيدة، تعني نوعاً من (التفلية) للكتاب، ومحاولة إضفاء نوع من التنظيم على محتواه الداخلي من أجل تسهيل استيعابه.","pg":68},{"term":"النقد","def":"إن النقد نوع من التثمين والتقييم الشامل للمنتج المعرفي وتحديد موقف جلي منه.","pg":79},{"term":"التخصص","def":"إن التخصص هو أن يبني الإنسان معرفة مدققة في موضوع ما مكتفياً بالمعرفة العامة في باقي الموضوعات","pg":86},{"term":"القراءة المحورية","def":"القراءة المحورية، هي تلك القراءة التي تستهدف الوقوف على معلومات وأفكار ومفاهيم، تتعلق بموضوع معين","pg":88},{"term":"الانتقائية في العمل التاريخي","def":"الانتقاء الذي يقوم به المؤرخ يجعل البنيان التاريخي كله انتقائياً","pg":102},{"term":"التعليل","def":"ومن المعلوم جيداً أن اليونان اخترعوا (التعليل) من أجل تلافي الثغرات التي يتركها الاستقراء الناقص","pg":103}],"links":[{"topic":"التعلم مدى الحياة","pg":7},{"topic":"الإعلام والتثقف","pg":13},{"topic":"تربية الأبناء على القراءة","pg":19},{"topic":"إدارة الوقت","pg":24},{"topic":"المثابرة","pg":53},{"topic":"اللغة والمصطلح","pg":64},{"topic":"النقد والحوار","pg":79},{"topic":"التخصص والبحث العلمي","pg":86},{"topic":"قراءة التاريخ","pg":97}]};
